pred=[('b_absent','b==ABSENT'),('b_branch','|| short-circuit branch'),('a_present','a!=ABSENT'),('a_branch','&& short-circuit branch'),('order','timestamp_a<=timestamp_b'),('result','comparison bool expression source->take_left received')]
bindings=[('a_binding','expanded/old initializer value8 source->named a8'),('b_binding','expanded/old initializer value8 source->named b8')]
ids=lambda load:[f'{load}.{id}'for id,_ in new_ops]
# Scalar stream remains in source order; payload copies have distinct groups and
