A=ids('A');B=ids('B');TA=ids('TA');TB=ids('TB')
blocks=[A+['a_binding',B[0]],B[1:]+['b_binding','b_absent','b_branch'],['a_present','a_branch']+TA,TB+['order','result']]
assert [len(b)for b in blocks]==[16,16,16,16]
